import java.util.*;import java.lang.reflect.Constructor;
import com.koios.*;import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.player.*;import com.koios.game.model.mob.*;import com.koios.game.model.item.*;import com.koios.game.map.*;import com.koios.network.*;import com.koios.client.stream.Stream;

/** Server-confirmed presentation, boss timing and LOS regressions; no desktop client. */
public final class CombatPresentationCheck {
 static int checks,index=50;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static final class Fixture implements AutoCloseable {
  final Player p;final MapRuns.Run run;
  Fixture()throws Exception{p=PrototypeIntegrationCheck.player("combatcue"+index,index++);p.setAttribute("starter-claimed",true);p.setAttribute("intro-complete",true);p.setAttribute("tutorial-stage",11);MapRuns.home(p);PrototypeIntegrationCheck.idle(p);p.getInventory().set(0,MapRuns.map(1,0,1));MapRuns.start(p,0,false);PrototypeIntegrationCheck.idle(p);run=MapRuns.run(p);for(MapRuns.MapMob mob:new ArrayList<>(run.mobs))MobManager.remove(mob);run.mobs.clear();}
  MapRuns.MapMob mob(Location at,boolean boss)throws Exception{Constructor<MapRuns.MapMob> ctor=MapRuns.MapMob.class.getDeclaredConstructor(Player.class,Location.class,MapRuns.Run.class,boolean.class);ctor.setAccessible(true);MapRuns.MapMob mob=ctor.newInstance(p,at,run,boss);MobManager.spawn(mob);run.mobs.add(mob);return mob;}
  Location area(int width,int height,int role){for(Location at:MapRuns.reachable(run.spawn,60)){if(role>=0&&Math.floorMod(at.getX()*31+at.getY()+run.layout,6)!=role)continue;boolean open=true;for(int x=0;x<width;x++)for(int y=0;y<height;y++)if(MapRegion.getClipping(at.getX()+x,at.getY()+y,0)!=0)open=false;if(open)return at;}throw new AssertionError("No open combat fixture area");}
  void stand(Location at){p.setPosition(at);PrototypeIntegrationCheck.idle(p);}
  List<GamePacket> packets(){return ((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets;}
  public void close(){MapRuns.cleanup(p);}
 }
 static List<String> channel(Fixture fixture,int after,int widget){List<String> result=new ArrayList<>();for(int i=after;i<fixture.packets().size();i++){GamePacket packet=fixture.packets().get(i);if(packet.getOpcode()!=126)continue;byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);Stream stream=new Stream(bytes);String value=stream.readString();if(stream.currentOffset+2<=bytes.length&&stream.method435()==widget)result.add(value);}return result;}
 static double pool(Player p){return p.getArpgVitals().life()+p.getArpgVitals().shield();}
 static int[] event(String text){String[] parts=text.split("\\|");check(parts.length==7,"Combat event has the agreed seven integer fields");int[] result=new int[7];for(int i=0;i<7;i++)result[i]=Integer.parseInt(parts[i]);return result;}
 static Location offset(Location at,int x,int y){return new Location(at.getX()+x,at.getY()+y,0);}
 public static void main(String[] args)throws Exception{
  PrototypeIntegrationCheck.loaded();
  for(int role:new int[]{2,5})try(Fixture fixture=new Fixture()){
   Location area=fixture.area(5,4,role);MapRuns.MapMob caster=fixture.mob(area,false);fixture.stand(offset(area,3,0));
   Item defence=new Item(22426);defence.setRoll(new ItemRoll(ItemRoll.Rarity.NORMAL,1,1,true,0,Collections.singletonList(new ItemRoll.Affix("cue_defence",ItemRoll.Layer.BASE_IMPLICIT,1,new Modifier(Stat.ENERGY_SHIELD,Modifier.Operation.FLAT,20),new Modifier(Stat.FIRE_RESISTANCE,Modifier.Operation.FLAT,75),new Modifier(Stat.COLD_RESISTANCE,Modifier.Operation.FLAT,75)))));fixture.p.getEquipment().set(4,defence);fixture.p.getArpgVitals().refill(fixture.p.getArpgStats());double before=pool(fixture.p),life=fixture.p.getArpgVitals().life();int after=fixture.packets().size();fixture.run.ticks=4;MapRuns.tick(fixture.p);List<String> events=channel(fixture,after,65525);check(events.size()==1,"Executed caster attack emits one presentation event");int[] cue=event(events.get(0));check(cue[0]==(role==2?6:7)&&cue[1]==caster.getX()&&cue[2]==caster.getY()&&cue[3]==fixture.p.getX()&&cue[4]==fixture.p.getY(),"Fire/cold bolt follows actual attacker and target coordinates");check(cue[5]==Math.round(before-pool(fixture.p))&&cue[5]<2&&cue[6]==0,"Bolt feedback reports mitigated Life+ES loss, never raw damage or a false critical");check(fixture.p.getArpgVitals().life()==life,"Energy Shield absorbs this elemental test hit");
  }
  try(Fixture fixture=new Fixture()){
   Location area=fixture.area(5,4,2);MapRuns.MapMob caster=fixture.mob(area,false);fixture.stand(offset(area,3,0));MapRegion.getRegion(area.getX()+1,area.getY()).setClip(area.getX()+1,area.getY(),0,0xFFFFFF);double before=pool(fixture.p);int after=fixture.packets().size();fixture.run.ticks=4;MapRuns.tick(fixture.p);check(pool(fixture.p)==before&&channel(fixture,after,65525).isEmpty(),"A wall-blocked caster neither damages nor emits a false attack");check(caster.getFollowing().isFollowing(),"A wall-blocked caster seeks a path instead of remaining stuck in range");Location original=caster.getLocation().copy();for(int tick=0;tick<20;tick++){caster.getMovementHandler().resetMoveDirections();caster.update();MapRuns.tick(fixture.p);}check(!caster.getLocation().equals(original)&&com.koios.game.map.path.StraightPathFinder.isInteractionPathClear(caster.getLocation(),fixture.p.getLocation()),"Blocked caster actually repositions to regain line of sight");check(!channel(fixture,after,65525).isEmpty(),"Caster resumes firing after repositioning around the wall");
  }
  try(Fixture fixture=new Fixture()){
   Location area=fixture.area(7,5,-1);MapRuns.MapMob boss=fixture.mob(area,true);fixture.stand(offset(area,2,0));double before=pool(fixture.p);int after=fixture.packets().size();fixture.run.nextSlam=12;fixture.run.ticks=11;MapRuns.tick(fixture.p);check(fixture.run.slam!=null&&fixture.run.slamAt==15,"Boss schedules a three-tick windup on an impact/basic-attack boundary");List<String> hazards=channel(fixture,after,65527);check(hazards.size()==1&&hazards.get(0).equals(fixture.p.getX()+"|"+fixture.p.getY()+"|2|1800"),"Boss hazard advertises matching tile radius and 1800ms windup");MapRuns.tick(fixture.p);MapRuns.tick(fixture.p);check(pool(fixture.p)==before,"Boss does not deal damage during its windup");MapRuns.tick(fixture.p);List<String> events=channel(fixture,after,65525);check(events.size()==1,"Slam impact emits one server-confirmed event");int[] cue=event(events.get(0));check(cue[0]==8&&cue[5]==24&&before-pool(fixture.p)==24,"Impact does not stack a normal melee hit on the same tick");check(cue[1]==boss.getX()&&cue[2]==boss.getY()&&cue[3]==fixture.p.getX()&&cue[4]==fixture.p.getY(),"Slam impact event identifies boss and marked ground");check(MapRuns.objectiveText(fixture.p).contains("RECOVERING"),"Boss recovery window is explicit to the player");double afterImpact=pool(fixture.p);fixture.run.ticks=19;MapRuns.tick(fixture.p);check(pool(fixture.p)<afterImpact,"Boss resumes normal attacks after recovery");
  }
  try(Fixture fixture=new Fixture()){
   Location area=fixture.area(8,5,-1);fixture.mob(area,true);fixture.stand(offset(area,2,0));fixture.run.nextSlam=12;fixture.run.ticks=11;MapRuns.tick(fixture.p);Location marked=fixture.run.slam.copy();fixture.stand(offset(area,5,0));double before=pool(fixture.p);int after=fixture.packets().size();MapRuns.tick(fixture.p);MapRuns.tick(fixture.p);MapRuns.tick(fixture.p);List<String> events=channel(fixture,after,65525);check(pool(fixture.p)==before&&events.size()==1,"Leaving the marked tiles avoids the slam");int[] cue=event(events.get(0));check(cue[0]==8&&cue[3]==marked.getX()&&cue[4]==marked.getY()&&cue[5]==0,"A dodged slam still impacts the original marked ground with zero player damage");
  }
  try(Fixture fixture=new Fixture()){
   Location area=fixture.area(7,5,-1);fixture.mob(area,true);fixture.stand(offset(area,3,0));MapRegion.getRegion(area.getX()+2,area.getY()).setClip(area.getX()+2,area.getY(),0,0xFFFFFF);fixture.run.nextSlam=0;int after=fixture.packets().size();MapRuns.tick(fixture.p);check(fixture.run.slam==null&&channel(fixture,after,65527).isEmpty(),"Boss cannot start a slam through a room wall");
  }
  for(int cancel=0;cancel<3;cancel++)try(Fixture fixture=new Fixture()){
   Location area=fixture.area(7,5,-1);MapRuns.MapMob boss=fixture.mob(area,true);fixture.stand(offset(area,2,0));fixture.run.nextSlam=0;MapRuns.tick(fixture.p);check(fixture.run.slam!=null,"Cancellation fixture has an active windup");int after=fixture.packets().size();if(cancel==0)MapRuns.home(fixture.p);else if(cancel==1)MapRuns.death(fixture.p);else boss.hurt(999999,fixture.p);check(fixture.run.slam==null&&channel(fixture,after,65527).contains(""),"Home, death or boss kill clears the telegraph immediately");for(int tick=0;tick<4;tick++)MapRuns.tick(fixture.p);check(channel(fixture,after,65525).isEmpty(),"Cancelled windup cannot emit a stale impact");
  }
  System.out.println("Passed "+checks+" combat presentation, LOS and boss timing checks.");
 }
}

